#!/bin/bash\n# ============================================================================\n# Hermes Agent v0.21.2 - Complete Installation Package\n# Built by Nous Research - MIT License\n# Release: v2026.9.11\n# ============================================================================\n# \n# هذا الملف يحتوي على كل ما تحتاجه لتثبيت Hermes Agent\n# This file contains everything needed to install Hermes Agent\n#\n# الاستخدام / Usage:\n#   chmod +x hermes-agent-v0.21.2.sh\n#   ./hermes-agent-v0.21.2.sh\n# ============================================================================\n\nset -e\n\n# ============================================================================\n# Configuration\n# ============================================================================\nVERSION=\"0.21.2\"\nRELEASE=\"v2026.9.11\"\nHERMES_HOME=\"${HERMES_HOME:-$HOME/.hermes}\"\nREPO_URL=\"https://github.com/Tahar0061/hermes-agent-build.git\"\nPYTHON_VERSION=\"3.11\"\n\n# Colors\nBLUE='\\033[0;34m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nRED='\\033[0;31m'\nNC='\\033[0m'\n\n# ============================================================================\n# Banner\n# ============================================================================\nprint_banner() {\n    clear\n    echo -e \"${BLUE}\"\n    echo \"╔════════════════════════════════════════════════════════════════╗\"\n    echo \"║                                                                ║\"\n    echo \"║   🤖 Hermes Agent v${VERSION} - Complete Installer             ║\"\n    echo \"║      Release: ${RELEASE}                                       ║\"\n    echo \"║      Built by Nous Research                                   ║\"\n    echo \"║                                                                ║\"\n    echo \"╚════════════════════════════════════════════════════════════════╝\"\n    echo -e \"${NC}\"\n}\n\n# ============================================================================\n# Helper Functions\n# ============================================================================\nprint_step() {\n    echo -e \"${BLUE}[*]${NC} $1\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}[✓]${NC} $1\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}[⚠]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[✗]${NC} $1\"\n}\n\n# ============================================================================\n# System Detection\n# ============================================================================\ndetect_os() {\n    if [[ \"$OSTYPE\" == \"linux-gnu\"* ]]; then\n        if grep -qi microsoft /proc/version; then\n            echo \"wsl2\"\n        else\n            echo \"linux\"\n        fi\n    elif [[ \"$OSTYPE\" == \"darwin\"* ]]; then\n        echo \"macos\"\n    elif [[ \"$OSTYPE\" == \"linux-android\" ]]; then\n        echo \"termux\"\n    else\n        echo \"unknown\"\n    fi\n}\n\ndetect_distro() {\n    if [ -f /etc/os-release ]; then\n        . /etc/os-release\n        echo $ID\n    else\n        echo \"unknown\"\n    fi\n}\n\ndetect_package_manager() {\n    if command -v apt &> /dev/null; then\n        echo \"apt\"\n    elif command -v yum &> /dev/null; then\n        echo \"yum\"\n    elif command -v dnf &> /dev/null; then\n        echo \"dnf\"\n    elif command -v pacman &> /dev/null; then\n        echo \"pacman\"\n    elif command -v brew &> /dev/null; then\n        echo \"brew\"\n    else\n        echo \"none\"\n    fi\n}\n\n# ============================================================================\n# Installation Steps\n# ============================================================================\ninstall_python() {\n    print_step \"Checking Python installation...\"\n    \n    if command -v python3 &> /dev/null; then\n        PYTHON_VER=$(python3 --version | cut -d' ' -f2)\n        print_success \"Python $PYTHON_VER already installed\"\n        return 0\n    fi\n    \n    print_warning \"Python not found. Installing Python 3.11...\"\n    \n    OS=$(detect_os)\n    PKG_MANAGER=$(detect_package_manager)\n    \n    case $OS in\n        linux|wsl2)\n            case $PKG_MANAGER in\n                apt)\n                    sudo apt-get update\n                    sudo apt-get install -y python3 python3-pip python3-venv\n                    ;;\n                yum|dnf)\n                    sudo $PKG_MANAGER install -y python3 python3-pip python3-devel\n                    ;;\n                pacman)\n                    sudo pacman -S python python-pip\n                    ;;\n                *)\n                    print_error \"Package manager not supported\"\n                    return 1\n                    ;;\n            esac\n            ;;\n        macos)\n            if ! command -v brew &> /dev/null; then\n                print_step \"Installing Homebrew...\"\n                /bin/bash -c \"$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)\"\n            fi\n            brew install python@3.11\n            ;;\n        termux)\n            pkg install -y python\n            ;;\n        *)\n            print_error \"Unsupported OS: $OS\"\n            return 1\n            ;;\n    esac\n    \n    print_success \"Python installed successfully\"\n}\n\ninstall_uv() {\n    print_step \"Checking uv installation...\"\n    \n    if command -v uv &> /dev/null; then\n        UV_VER=$(uv --version)\n        print_success \"$UV_VER already installed\"\n        return 0\n    fi\n    \n    print_warning \"Installing uv (Python package manager)...\"\n    \n    OS=$(detect_os)\n    \n    if [ \"$OS\" = \"macos\" ]; then\n        brew install uv\n    else\n        curl -LsSf https://astral.sh/uv/install.sh | sh\n        export PATH=\"$HOME/.cargo/bin:$PATH\"\n    fi\n    \n    print_success \"uv installed successfully\"\n}\n\ninstall_git() {\n    print_step \"Checking Git installation...\"\n    \n    if command -v git &> /dev/null; then\n        GIT_VER=$(git --version)\n        print_success \"$GIT_VER already installed\"\n        return 0\n    fi\n    \n    print_warning \"Installing Git...\"\n    \n    OS=$(detect_os)\n    PKG_MANAGER=$(detect_package_manager)\n    \n    case $OS in\n        linux|wsl2)\n            case $PKG_MANAGER in\n                apt)\n                    sudo apt-get update\n                    sudo apt-get install -y git\n                    ;;\n                yum|dnf)\n                    sudo $PKG_MANAGER install -y git\n                    ;;\n                pacman)\n                    sudo pacman -S git\n                    ;;\n            esac\n            ;;\n        macos)\n            brew install git\n            ;;\n    esac\n    \n    print_success \"Git installed successfully\"\n}\n\nsetup_hermes_home() {\n    print_step \"Setting up Hermes home directory: $HERMES_HOME\"\n    \n    mkdir -p \"$HERMES_HOME\"\n    mkdir -p \"$HERMES_HOME/venv\"\n    mkdir -p \"$HERMES_HOME/logs\"\n    mkdir -p \"$HERMES_HOME/backups\"\n    mkdir -p \"$HERMES_HOME/skills\"\n    \n    print_success \"Directory structure created\"\n}\n\nclone_repository() {\n    print_step \"Cloning Hermes Agent from GitHub...\"\n    \n    if [ -d \"$HERMES_HOME/hermes-agent\" ]; then\n        print_warning \"Repository already exists. Updating...\"\n        cd \"$HERMES_HOME/hermes-agent\"\n        git pull origin main\n        cd -\n    else\n        git clone --depth 1 \"$REPO_URL\" \"$HERMES_HOME/hermes-agent\"\n    fi\n    \n    print_success \"Repository ready\"\n}\n\ncreate_venv() {\n    print_step \"Creating Python virtual environment...\"\n    \n    uv venv \"$HERMES_HOME/venv\" --python $PYTHON_VERSION\n    \n    print_success \"Virtual environment created\"\n}\n\ninstall_hermes() {\n    print_step \"Installing Hermes Agent dependencies...\"\n    print_warning \"This may take several minutes...\"\n    \n    source \"$HERMES_HOME/venv/bin/activate\"\n    \n    cd \"$HERMES_HOME/hermes-agent\"\n    uv pip install -e \".[all]\"\n    cd -\n    \n    print_success \"Hermes Agent installed successfully\"\n}\n\nsetup_path() {\n    print_step \"Configuring PATH...\"\n    \n    # Detect shell\n    SHELL_RC=\"\"\n    if [ -f \"$HOME/.bashrc\" ]; then\n        SHELL_RC=\"$HOME/.bashrc\"\n    elif [ -f \"$HOME/.zshrc\" ]; then\n        SHELL_RC=\"$HOME/.zshrc\"\n    elif [ -f \"$HOME/.profile\" ]; then\n        SHELL_RC=\"$HOME/.profile\"\n    fi\n    \n    if [ -z \"$SHELL_RC\" ]; then\n        print_warning \"Could not find shell configuration file\"\n        return 1\n    fi\n    \n    # Add to PATH if not already there\n    if ! grep -q \"$HERMES_HOME/venv/bin\" \"$SHELL_RC\"; then\n        echo \"\" >> \"$SHELL_RC\"\n        echo \"# Hermes Agent v${VERSION}\" >> \"$SHELL_RC\"\n        echo \"export HERMES_HOME=\\\"$HERMES_HOME\\\"\" >> \"$SHELL_RC\"\n        echo \"export PATH=\\\"$HERMES_HOME/venv/bin:\\$PATH\\\"\" >> \"$SHELL_RC\"\n        print_success \"Added to $SHELL_RC\"\n    else\n        print_success \"Already in $SHELL_RC\"\n    fi\n}\n\n# ============================================================================\n# Main Installation\n# ============================================================================\nmain() {\n    print_banner\n    \n    OS=$(detect_os)\n    \n    if [ \"$OS\" = \"unknown\" ]; then\n        print_error \"Unsupported operating system: $OSTYPE\"\n        echo \"\"\n        echo \"Supported systems:\"\n        echo \"  - Linux (Ubuntu, Debian, Fedora, Arch, etc.)\"\n        echo \"  - macOS (Intel and Apple Silicon)\"\n        echo \"  - WSL2 (Windows Subsystem for Linux)\"\n        echo \"  - Termux (Android)\"\n        echo \"\"\n        echo \"For Windows native support, use the PowerShell installer.\"\n        exit 1\n    fi\n    \n    print_success \"Detected OS: $OS\"\n    echo \"\"\n    \n    # Install dependencies\n    install_python || exit 1\n    install_git || exit 1\n    install_uv || exit 1\n    \n    echo \"\"\n    \n    # Setup Hermes\n    setup_hermes_home || exit 1\n    clone_repository || exit 1\n    create_venv || exit 1\n    install_hermes || exit 1\n    setup_path || exit 1\n    \n    echo \"\"\n    echo -e \"${GREEN}\"\n    echo \"╔════════════════════════════════════════════════════════════════╗\"\n    echo \"║                                                                ║\"\n    echo \"║              ✓ Installation Complete! 🎉                       ║\"\n    echo \"║                                                                ║\"\n    echo \"╚════════════════════════════════════════════════════════════════╝\"\n    echo -e \"${NC}\"\n    \n    echo \"\"\n    echo -e \"${YELLOW}📋 Next Steps:${NC}\"\n    echo \"\"\n    echo -e \"  1. ${BLUE}Reload your shell:${NC}\"\n    if [ -f \"$HOME/.bashrc\" ]; then\n        echo -e \"     ${BLUE}source ~/.bashrc${NC}\"\n    else\n        echo -e \"     ${BLUE}source ~/.zshrc${NC}\"\n    fi\n    echo \"\"\n    echo -e \"  2. ${BLUE}Start Hermes:${NC}\"\n    echo -e \"     ${BLUE}hermes${NC}\"\n    echo \"\"\n    echo -e \"  3. ${BLUE}Run setup wizard:${NC}\"\n    echo -e \"     ${BLUE}hermes setup${NC}\"\n    echo \"\"\n    echo -e \"${BLUE}📚 Documentation:${NC} https://hermes-agent.nousresearch.com/docs\"\n    echo -e \"${BLUE}💬 Discord Community:${NC} https://discord.gg/NousResearch\"\n    echo -e \"${BLUE}🐛 Report Issues:${NC} https://github.com/NousResearch/hermes-agent/issues\"\n    echo \"\"\n    echo -e \"${GREEN}Thank you for using Hermes Agent! 🚀${NC}\"\n    echo \"\"\n}\n\n# ============================================================================\n# Run Main\n# ============================================================================\nif [ \"${BASH_SOURCE[0]}\" = \"${0}\" ]; then\n    main \"$@\"\nfi\n"